 let text='The catalogue associates '+count.toLocaleString()+' record'+(count===1?'':'s')+' with “'+a.displayName+'”.';
 if(examples.length)text+=' '+(examples.length===1?'A linked entry reads ':'Linked entries include ')+examples.map(r=>'“'+shortTitle(r)+'”').join(' and ')+'.';
 const years=records.map(r=>r.year).filter(Number.isFinite);
